(async () => {
  if (!game.user?.isGM) return ui.notifications?.error("GM only.");
  const report = [];
  const sysUpd = (c) => ({
    "system.tier": c.system.tier, "system.details.level": c.system.details.level, "system.details.tier": c.system.details.tier,
    "system.attributes": c.system.attributes, "system.derived": c.system.derived, "system.notes": c.system.notes,
    "system.tags": c.system.tags, "system.details.biography": c.system.details.biography,
    "flags.fourththing.rfi.actor": c.flags.fourththing.rfi.actor
  });
  async function restat(doc, c, where) {
    if (!doc) { report.push({ where, name: c.name, result: "MISSING" }); return; }
    const before = { guard: doc.system?.derived?.guard?.value, integ: doc.system?.derived?.integrity?.max, strikes: doc.system?.derived?.strikes?.value };
    if (!DRY_RUN) {
      await doc.update(sysUpd(c));
      const ids = doc.items.map(i => i.id); if (ids.length) await doc.deleteEmbeddedDocuments("Item", ids);
      await doc.createEmbeddedDocuments("Item", c.items, { keepId: true });
    }
    const after = DRY_RUN ? "(dry)" : { guard: doc.system?.derived?.guard?.value, integ: doc.system?.derived?.integrity?.max, strikes: doc.system?.derived?.strikes?.value };
    report.push({ where, name: c.name, result: DRY_RUN ? "would restat" : "restat", before: JSON.stringify(before), after: JSON.stringify(after) });
  }
  async function createIn(c, where, opts) {
    const existing = where === "[pack]" ? await game.packs.get(PACK_ID)?.getDocument(c._id) : game.actors.get(c._id);
    if (existing) { report.push({ where, name: c.name, result: "exists — restat" }); return restat(existing, c, where); }
    if (!DRY_RUN) {
      const data = foundry.utils.deepClone(c); data.folder = FOLDER_ID;
      const made = await Actor.create(data, { keepId: true, ...opts });
      report.push({ where, name: c.name, result: "created", id: made?.id, guard: made?.system?.derived?.guard?.value, integ: made?.system?.derived?.integrity?.max });
    } else report.push({ where, name: c.name, result: "would create" });
  }
  const pack = game.packs.get(PACK_ID);
  if (!pack) return ui.notifications?.error(`Pack not found: ${PACK_ID}`);
  const wasLocked = pack.locked;
  try {
    if (!DRY_RUN && wasLocked) await pack.configure({ locked: false });
    const pc = await pack.getDocument(CANON.commander._id); if (pc?.name !== CANON.commander.name) report.push({ where: "[pack]", name: CANON.commander.name, result: "name mismatch — skipped" }); else await restat(pc, CANON.commander, "[pack]");
    const pr = await pack.getDocument(CANON.roadBandit._id); if (pr?.name !== CANON.roadBandit.name) report.push({ where: "[pack]", name: CANON.roadBandit.name, result: "name mismatch — skipped" }); else if (!DRY_RUN) { await pr.update({ "system.derived": CANON.roadBandit.system.derived }); report.push({ where: "[pack]", name: pr.name, result: "derived snapshot synced" }); } else report.push({ where: "[pack]", name: pr.name, result: "would sync derived snapshot" });
    await createIn(CANON.hexknight, "[pack]", { pack: PACK_ID });
    await createIn(CANON.drownedSouth, "[pack]", { pack: PACK_ID });
  } finally { if (!DRY_RUN && wasLocked) await pack.configure({ locked: true }); }
  const wc = game.actors.get(WORLD_COMMANDER_ID);
  if (wc?.name === CANON.commander.name) await restat(wc, CANON.commander, "[world]"); else report.push({ where: "[world]", name: CANON.commander.name, result: "world actor not found by id — skipped" });
  console.table(report);
  ui.notifications?.info(`[restamp-bandits] ${DRY_RUN ? "DRY RUN" : "APPLIED"} — ${report.length} row(s); see console.table.`);
  return report;
})();
